'use client'
import React, { useState, useEffect } from 'react';
import { Star, Moon, Sun, Globe, ChevronUp } from 'lucide-react';

export default function Footer() {
  const [theme, setTheme] = useState('cosmic');
  const [starCount, setStarCount] = useState(50);
  const [showScrollTop, setShowScrollTop] = useState(false);
  
  // Check scroll position to show/hide scroll to top button
  useEffect(() => {
    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 300);
    };
    
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);
  
  // Scroll to top function
  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };
  
  // Generate random stars
  const generateStars = () => {
    return Array.from({ length: starCount }).map((_, i) => {
      const size = Math.random() * 3 + 1;
      const top = Math.random() * 100;
      const left = Math.random() * 100;
      const animationDuration = Math.random() * 3 + 2;
      
      return (
        <div
          key={i}
          className="absolute rounded-full bg-white"
          style={{
            width: `${size}px`,
            height: `${size}px`,
            top: `${top}%`,
            left: `${left}%`,
            opacity: Math.random() * 0.7 + 0.3,
            animation: `twinkle ${animationDuration}s infinite alternate`
          }}
        />
      );
    });
  };
  
  const currentYear = new Date().getFullYear();
  
  return (
    <footer className="relative overflow-hidden">
      {/* Cosmic Background with CSS Animation */}
      <div 
        className={`relative py-16 px-4 transition-all duration-500 ${
          theme === 'cosmic' 
            ? 'bg-gradient-to-r from-purple-900 via-indigo-800 to-blue-900' 
            : theme === 'light' 
              ? 'bg-gradient-to-r from-blue-100 via-purple-100 to-pink-100' 
              : 'bg-gradient-to-r from-gray-900 via-gray-800 to-gray-700'
        }`}
      >
        {/* Animated stars (visible in cosmic and dark themes) */}
        {(theme === 'cosmic' || theme === 'dark') && generateStars()}
        
        {/* Interactive orbiting planet */}
        <div className="absolute w-48 h-48 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 opacity-10 blur-xl animate-spin top-0 right-0" style={{ animationDuration: '20s' }} />
        
        <div className="container mx-auto">
          {/* Theme Switcher */}
          <div className="flex justify-center mb-8">
            <div className="bg-black/30 backdrop-blur-md p-1 rounded-full flex">
              <button 
                onClick={() => setTheme('cosmic')}
                className={`p-2 rounded-full ${theme === 'cosmic' ? 'bg-purple-500 text-white' : 'text-gray-300'}`}
              >
                <Globe size={20} />
              </button>
              <button 
                onClick={() => setTheme('light')}
                className={`p-2 rounded-full ${theme === 'light' ? 'bg-yellow-400 text-white' : 'text-gray-300'}`}
              >
                <Sun size={20} />
              </button>
              <button 
                onClick={() => setTheme('dark')}
                className={`p-2 rounded-full ${theme === 'dark' ? 'bg-gray-700 text-white' : 'text-gray-300'}`}
              >
                <Moon size={20} />
              </button>
            </div>
          </div>
          
          {/* Main Footer Content */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-12 relative z-10">
            {/* Company Info with Animated Text */}
            <div className="text-center md:text-left">
              <h3 className="text-xl font-bold mb-4 text-white">Nexus Dashboard</h3>
              <p className="text-gray-300 mb-4">Expanding your digital universe, one connection at a time.</p>
              <p className="text-sm text-gray-400">&copy; {currentYear} Nexus Dashboard. All Rights Reserved.</p>
            </div>
            
            {/* Links with Hover Effects */}
            <div className="flex flex-col space-y-4 items-center md:items-start">
              <h3 className="text-xl font-bold mb-2 text-white">Quick Links</h3>
              <div className="flex flex-col space-y-2">
                {['Home', 'About', 'Services', 'Blog', 'Contact'].map((link) => (
                  <a 
                    key={link} 
                    href={`/${link.toLowerCase()}`} 
                    className="text-gray-300 hover:text-white transform hover:translate-x-2 transition-all duration-300 flex items-center"
                  >
                    <span className="mr-2 opacity-0 group-hover:opacity-100 transition-opacity">•</span>
                    {link}
                  </a>
                ))}
              </div>
            </div>
            
            {/* Combined Legal and Social Links */}
            <div className="flex flex-col items-center md:items-start">
              <h3 className="text-xl font-bold mb-4 text-white">Connect With Us</h3>
              
              {/* Social Media with Animated Icons */}
              <div className="flex space-x-4 mb-6">
                {[
                  { name: 'Facebook', icon: 'M9 8H7v4h2v12h5V12h3.642L18 8h-4V6.5C14 6.102 14.149 6 14.5 6H18V2h-3.5C11.42 2 9 4.012 9 6.5V8z' },
                  { name: 'Twitter', icon: 'M24 4.557c-.883.392-1.833.654-2.828.775 1.017-.611 1.798-1.574 2.165-2.724-.95.564-2.005.974-3.127 1.195C19.64 2.69 18.337 2 16.905 2c-2.691 0-4.877 2.185-4.877 4.877 0 .383.043.759.127 1.118C7.728 7.803 4.1 5.882 1.671 2.905c-.422.725-.664 1.565-.664 2.466 0 1.7.866 3.2 2.18 4.08-.803-.026-1.56-.247-2.228-.616v.062c0 2.37 1.685 4.348 3.918 4.794-.411.112-.845.172-1.292.172-.315 0-.623-.03-.923-.087.623 1.945 2.431 3.363 4.576 3.404-1.676 1.313-3.789 2.096-6.086 2.096-.395 0-.785-.023-1.17-.067C2.292 21.002 5.017 22 7.958 22c9.548 0 14.776-7.91 14.776-14.776 0-.225-.005-.449-.015-.673A10.576 10.576 0 0024 4.557z' },
                  { name: 'Instagram', icon: 'M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zM12 0C8.741 0 8.333.014 7.053.072 2.695.272.273 2.69.073 7.052.014 8.333 0 8.741 0 12c0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98C8.333 23.986 8.741 24 12 24c3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98C15.668.014 15.259 0 12 0zm0 5.838a6.162 6.162 0 100 12.324 6.162 6.162 0 000-12.324zM12 16a4 4 0 110-8 4 4 0 010 8zm6.406-11.845a1.44 1.44 0 100 2.881 1.44 1.44 0 000-2.881z' },
                  { name: 'LinkedIn', icon: 'M4.98 3.5c0 1.381-1.11 2.5-2.48 2.5s-2.48-1.119-2.48-2.5c0-1.38 1.11-2.5 2.48-2.5s2.48 1.12 2.48 2.5zm.02 4.5h-5v16h5v-16zm7.982 0h-4.968v16h4.969v-8.399c0-4.67 6.029-5.052 6.029 0v8.399h4.988v-10.131c0-7.88-8.922-7.593-11.018-3.714v-2.155z' }
                ].map((social) => (
                  <a 
                    key={social.name} 
                    href={`https://${social.name.toLowerCase()}.com`} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="group"
                  >
                    <div className="w-10 h-10 rounded-full flex items-center justify-center bg-white/10 backdrop-blur-md hover:bg-white/20 transform hover:scale-110 transition-all duration-300">
                      <svg 
                        xmlns="http://www.w3.org/2000/svg" 
                        className="h-5 w-5 text-white" 
                        fill="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path d={social.icon} />
                      </svg>
                    </div>
                  </a>
                ))}
              </div>
              
              {/* Legal Links */}
              <div className="flex flex-col md:flex-row space-y-2 md:space-y-0 md:space-x-4">
                <a href="/privacy" className="text-sm text-gray-400 hover:text-white transition-colors">
                  Privacy Policy
                </a>
                <a href="/terms" className="text-sm text-gray-400 hover:text-white transition-colors">
                  Terms of Service
                </a>
              </div>
            </div>
          </div>
          
          {/* Newsletter Subscription with Animation */}
          <div className="mt-12 max-w-md mx-auto">
            <div className="bg-white/10 backdrop-blur-md rounded-lg p-6 transform hover:scale-105 transition-all duration-300">
              <h3 className="text-lg font-medium text-white mb-2">Join Our Cosmic Newsletter</h3>
              <p className="text-gray-300 text-sm mb-4">Stay updated with our latest features and releases</p>
              <div className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-2">
                <input 
                  type="email" 
                  placeholder="Enter your email" 
                  className="px-4 py-2 rounded-md bg-white/5 border border-white/20 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-purple-500 flex-grow"
                />
                <button className="px-4 py-2 bg-gradient-to-r from-purple-500 to-pink-500 rounded-md text-white font-medium hover:from-purple-600 hover:to-pink-600 transition-colors">
                  Subscribe
                </button>
              </div>
            </div>
          </div>
        </div>
        
        {/* Scroll to top button */}
        <button 
          onClick={scrollToTop}
          className={`fixed bottom-6 right-6 w-12 h-12 rounded-full bg-purple-600 text-white flex items-center justify-center shadow-lg transform transition-all duration-300 ${
            showScrollTop ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10 pointer-events-none'
          }`}
        >
          <ChevronUp size={24} />
        </button>
      </div>
      
      {/* Animated Wave Separator */}
      <div className="w-full h-20 bg-gradient-to-b from-purple-900 to-transparent overflow-hidden">
        <svg 
          className="w-full h-full" 
          viewBox="0 0 1200 120" 
          preserveAspectRatio="none"
        >
          <path 
            d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z" 
            className="fill-current text-gray-900 opacity-20"
          />
        </svg>
      </div>
      
      {/* Global CSS for star animation */}
      <style jsx global>{`
        @keyframes twinkle {
          0% { opacity: 0.3; }
          100% { opacity: 1; }
        }
      `}</style>
    </footer>
  );
}